package com.circlenet.domain.health;import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import com.circlenet.domain.social.SocialPostRepository;import com.circlenet.domain.social.model.SocialPostEntity;import java.math.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;
class HealthServiceTest{HealthReportRepository reports;HealthMeasurementRepository measurements;SocialPostRepository posts;HealthService service;@BeforeEach void setup(){reports=mock(HealthReportRepository.class);measurements=mock(HealthMeasurementRepository.class);posts=mock(SocialPostRepository.class);service=new HealthService(reports,measurements,posts);when(reports.save(any())).thenAnswer(x->{HealthReportEntity e=x.getArgument(0);field(e,"id",9L);return e;});when(measurements.save(any())).thenAnswer(x->{HealthMeasurementEntity e=x.getArgument(0);field(e,"id",11L);return e;});when(measurements.findByReportId(anyLong())).thenReturn(List.of());}
 @Test void linksOnlyOwnersPrivateDiaryDocument(){SocialPostEntity post=new SocialPostEntity();post.setAuthorUserId(1L);post.setAudience("PRIVATE");post.setMediaKey("reports/a.pdf");when(posts.findById(5L)).thenReturn(Optional.of(post));var report=service.add(1L,new HealthService.ReportInput(5L,"Blood test","Lab",LocalDate.of(2026,8,20),null,List.of()));assertThat(report.sourcePostId()).isEqualTo(5L);verify(reports).save(any());}
 @Test void rejectsSomeoneElsesDocument(){SocialPostEntity post=new SocialPostEntity();post.setAuthorUserId(2L);post.setAudience("PRIVATE");post.setMediaKey("reports/a.pdf");when(posts.findById(5L)).thenReturn(Optional.of(post));assertThatThrownBy(()->service.add(1L,new HealthService.ReportInput(5L,"Blood test",null,LocalDate.now(),null,List.of()))).hasMessageContaining("private diary");}
 @Test void labelsOnlyAgainstEnteredLaboratoryRange(){HealthReportEntity report=new HealthReportEntity();field(report,"id",9L);report.setUserId(1L);report.setReportName("Test");report.setCollectedOn(LocalDate.now());HealthMeasurementEntity measurement=new HealthMeasurementEntity();field(measurement,"id",11L);measurement.setReportId(9L);measurement.setMetricName("Marker");measurement.setValue(new BigDecimal("12"));measurement.setUnit("u");measurement.setReferenceMax(new BigDecimal("10"));when(reports.findByUserIdOrderByCollectedOnDesc(1L)).thenReturn(List.of(report));when(measurements.findByReportId(9L)).thenReturn(List.of(measurement));assertThat(service.dashboard(1L).reports().get(0).measurements().get(0).rangeStatus()).isEqualTo("ABOVE");}
 private static void field(Object target,String name,Object value){try{var f=target.getClass().getDeclaredField(name);f.setAccessible(true);f.set(target,value);}catch(Exception e){throw new RuntimeException(e);}}}
